import { useAuth } from "@/_core/hooks/useAuth";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { BarcodeScannerDialog } from "@/components/BarcodeScannerDialog";
import { canQueryInventoryOverview } from "@/lib/inventoryAccess";
import { getInventorySubmissionRequirements } from "@/lib/inventorySubmission";
import { trpc } from "@/lib/trpc";
import { Archive, ArrowDownToLine, Building2, CheckCircle2, ChevronRight, CircleAlert, ClipboardCheck, FileCheck2, FilePlus2, FileText, Landmark, Loader2, PencilLine, Plus, ScanLine, Send, ShieldAlert, UsersRound, X } from "lucide-react";
import React, { ChangeEvent, FormEvent, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { useLocation } from "wouter";

const YEAR = new Date().getFullYear();
const expenseCodes = ["52.01", "52.02", "52.03", "52.04", "52.05", "52.06", "52.07", "52.08", "52.09", "52.10", "52.11", "52.12", "52.13", "52.14", "52.15", "52.16", "52.17", "52.18", "52.19", "52.20", "52.21", "52.22", "52.25", "52.26", "52.99"];
const docLabels: Record<string, string> = { opening_minutes: "Ata de Abertura", responsibility_term: "Termo de Responsabilidade", closing_minutes: "Ata de Encerramento" };
const issueLabels: Record<string, string> = { not_found: "Bem não localizado", outside_register: "Bem fora da carga", new_equipment: "Equipamento novo", transfer: "Transferência", donation: "Doação", guard_term: "Termo de guarda", other: "Outra situação" };
const statusLabels: Record<string, string> = { draft: "Em preparação", submitted: "Submetido", under_review: "Em análise", returned: "Devolvido", validated: "Validado" };
const statusClasses: Record<string, string> = { draft: "bg-stone-100 text-stone-700", submitted: "bg-amber-100 text-amber-800", under_review: "bg-sky-100 text-sky-800", returned: "bg-rose-100 text-rose-800", validated: "bg-emerald-100 text-emerald-800" };

const money = (value: string | number | null | undefined) => new Intl.NumberFormat("pt-PT", { style: "currency", currency: "BRL", minimumFractionDigits: 2 }).format(Number(value ?? 0));
const safeText = (value: FormDataEntryValue | null) => String(value ?? "").trim();
const createCommitteeMember = (isPresident = false) => ({ name: "", jobTitle: "", masp: "", isPresident });

function StatusBadge({ status }: { status: string }) { return <Badge className={`border-0 px-2.5 py-1 text-[11px] font-semibold ${statusClasses[status] || "bg-stone-100 text-stone-700"}`}>{statusLabels[status] || status}</Badge>; }

function Field({ label, children, className = "" }: { label: string; children: React.ReactNode; className?: string }) {
  return <div className={`space-y-1.5 ${className}`}><Label className="text-xs font-semibold text-[#3d564b]">{label}</Label>{children}</div>;
}

function EmptyState({ icon: Icon, title, children }: { icon: typeof Archive; title: string; children: React.ReactNode }) {
  return <div className="rounded-2xl border border-dashed border-[#c8d8cc] bg-[#fbfdf9] px-6 py-10 text-center"><div className="mx-auto flex size-11 items-center justify-center rounded-xl bg-[#eaf1e9] text-[#29604c]"><Icon className="size-5" /></div><h3 className="mt-4 text-base font-semibold text-[#1a3d32]">{title}</h3><div className="mt-2 text-sm leading-6 text-[#66786d]">{children}</div></div>;
}

function downloadCsv(rows: Array<Record<string, unknown>>, fileName: string) {
  if (!rows.length) return toast.info("Não existem dados para exportar com estes filtros.");
  const keys = Object.keys(rows[0]);
  const quote = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`;
  const content = [keys.map(quote).join(";"), ...rows.map(row => keys.map(key => quote(row[key])).join(";"))].join("\n");
  const url = URL.createObjectURL(new Blob(["\uFEFF", content], { type: "text/csv;charset=utf-8" }));
  const link = document.createElement("a"); link.href = url; link.download = `${fileName}.csv`; link.click(); URL.revokeObjectURL(url);
}

function Heading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="flex flex-col gap-5 border-b border-[#dbe6dc] pb-7 lg:flex-row lg:items-end lg:justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.2em] text-[#597566]">{eyebrow}</p><h1 className="mt-2 font-serif text-3xl font-semibold tracking-tight text-[#173b30] md:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#65796e]">{description}</p></div>{action}</div>;
}

export default function Home() {
  const { user, loading } = useAuth();
  const [location] = useLocation();
  const [year, setYear] = useState(YEAR);
  const managementRoute = location === "/gestao";
  if (loading || !user) return null;
  if (managementRoute && user.role === "admin") return <ManagementPanel year={year} setYear={setYear} />;
  return <SchoolWorkspace year={year} setYear={setYear} isManager={user.role === "admin"} viewerId={user.id} />;
}

function SchoolWorkspace({ year, setYear, isManager, viewerId }: { year: number; setYear: (year: number) => void; isManager: boolean; viewerId: number }) {
  const utils = trpc.useUtils();
  const schoolsQuery = trpc.school.list.useQuery({ viewerId });
  const categoriesQuery = trpc.catalog.expenseCategories.useQuery();
  const [schoolId, setSchoolId] = useState<number | null>(null);
  const [schoolSearch, setSchoolSearch] = useState("");
  const [schoolDialog, setSchoolDialog] = useState(false);
  const [editingSchool, setEditingSchool] = useState<any>(null);
  const [itemDialog, setItemDialog] = useState(false);
  const [editingItem, setEditingItem] = useState<any>(null);
  const [issueDialog, setIssueDialog] = useState(false);
  const [committeeDialog, setCommitteeDialog] = useState(false);
  const [notesDialog, setNotesDialog] = useState(false);
  const [accessDialog, setAccessDialog] = useState(false);
  const [committee, setCommittee] = useState([createCommitteeMember(true)]);
  const [notes, setNotes] = useState({ problemsFound: "", quantityDivergences: "", valueDivergences: "" });

  useEffect(() => { if (!schoolId && schoolsQuery.data?.length) setSchoolId(schoolsQuery.data[0].id); }, [schoolId, schoolsQuery.data]);
  const visibleSchoolIds = useMemo(() => (schoolsQuery.data ?? []).map((school: any) => school.id), [schoolsQuery.data]);
  const canLoadOverview = canQueryInventoryOverview(schoolId, visibleSchoolIds);
  const overviewQuery = trpc.inventory.overview.useQuery({ schoolId: schoolId ?? 0, year }, { enabled: canLoadOverview, retry: false });
  const createCycle = trpc.inventory.createCycle.useMutation({ onSuccess: () => { toast.success("Ciclo de inventário criado."); void overviewQuery.refetch(); } });
  const createSchool = trpc.school.create.useMutation({ onSuccess: async school => { toast.success("Escola registada."); await utils.school.list.invalidate(); setSchoolId(school.id); setSchoolDialog(false); } });
  const updateSchool = trpc.school.update.useMutation({ onSuccess: async () => { toast.success("Dados institucionais atualizados."); await Promise.all([utils.school.list.invalidate(), overviewQuery.refetch()]); setSchoolDialog(false); } });
  const addItem = trpc.inventory.addItem.useMutation({ onSuccess: async () => { toast.success("Item patrimonial incluído."); setItemDialog(false); setEditingItem(null); await overviewQuery.refetch(); } });
  const updateItem = trpc.inventory.updateItem.useMutation({ onSuccess: async () => { toast.success("Item patrimonial atualizado."); setItemDialog(false); setEditingItem(null); await overviewQuery.refetch(); } });
  const deleteItem = trpc.inventory.deleteItem.useMutation({ onSuccess: () => { toast.success("Item removido."); void overviewQuery.refetch(); } });
  const addIssue = trpc.inventory.addIssue.useMutation({ onSuccess: async () => { toast.success("Pendência registada."); setIssueDialog(false); await overviewQuery.refetch(); } });
  const deleteIssue = trpc.inventory.deleteIssue.useMutation({ onSuccess: () => { toast.success("Pendência removida."); void overviewQuery.refetch(); } });
  const setCommitteeMutation = trpc.inventory.setCommittee.useMutation({ onSuccess: async () => { toast.success("Subcomissão registada."); setCommitteeDialog(false); await overviewQuery.refetch(); } });
  const setNotesMutation = trpc.inventory.upsertNotes.useMutation({ onSuccess: async () => { toast.success("Registos complementares guardados."); setNotesDialog(false); await overviewQuery.refetch(); } });
  const uploadDocument = trpc.inventory.uploadDocument.useMutation({ onSuccess: async () => { toast.success("Documento recebido e associado à escola."); await overviewQuery.refetch(); }, onError: error => toast.error(error.message || "Não foi possível enviar o documento. Tente novamente.") });
  const removeDocument = trpc.inventory.removeDocument.useMutation({ onSuccess: () => { toast.success("Documento removido."); void overviewQuery.refetch(); }, onError: error => toast.error(error.message || "Não foi possível remover o documento.") });
  const submitCycle = trpc.inventory.submit.useMutation({ onSuccess: async () => { toast.success("Inventário submetido para validação."); await overviewQuery.refetch(); }, onError: error => toast.error(error.message || "Não foi possível submeter o inventário. Verifique as exigências pendentes.") });
  const overview = overviewQuery.data;
  const filteredSchools = useMemo(() => {
    const term = schoolSearch.trim().normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
    if (!term) return schoolsQuery.data ?? [];
    return (schoolsQuery.data ?? []).filter((school: any) => `${school.name} ${school.schoolCode ?? ""} ${school.city ?? ""}`.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().includes(term));
  }, [schoolSearch, schoolsQuery.data]);
  const cycle = overview?.cycle;
  const editable = cycle?.status === "draft" || cycle?.status === "returned";
  const canCreateCycle = Boolean(schoolId && !cycle);
  const totalValue = overview?.items?.reduce((sum: number, item: any) => sum + Number(item.totalValue), 0) ?? 0;
  const documentTypes = new Set(overview?.documents?.map((document: any) => document.documentType));
  const completion = [Boolean(cycle), (overview?.members?.length ?? 0) >= 1, (overview?.items?.length ?? 0) > 0, documentTypes.size === 3].filter(Boolean).length;
  const submissionRequirements = getInventorySubmissionRequirements({ itemCount: overview?.items?.length ?? 0, memberCount: overview?.members?.length ?? 0, documentTypes });

  const openCommittee = () => {
    const existing = overview?.members?.map((member: any) => ({ name: member.name, jobTitle: member.jobTitle, masp: member.masp, isPresident: Boolean(member.isPresident) }));
    setCommittee(existing?.length ? existing : [createCommitteeMember(true)]);
    setCommitteeDialog(true);
  };
  const openNotes = () => { setNotes({ problemsFound: overview?.notes?.problemsFound || "", quantityDivergences: overview?.notes?.quantityDivergences || "", valueDivergences: overview?.notes?.valueDivergences || "" }); setNotesDialog(true); };
  const handleSubmit = () => {
    if (!cycle) return;
    if (!submissionRequirements.ready) {
      toast.error(`Ainda faltam ${submissionRequirements.missing.length} exigência(s): ${submissionRequirements.missing.join(", ")}.`);
      return;
    }
    submitCycle.mutate({ cycleId: cycle.id });
  };
  const handleFile = async (event: ChangeEvent<HTMLInputElement>, documentType: "opening_minutes" | "responsibility_term" | "closing_minutes") => {
    const file = event.target.files?.[0]; if (!file) return;
    if (!["application/pdf", "image/jpeg", "image/png"].includes(file.type)) return toast.error("Envie PDF, JPG ou PNG.");
    if (file.size > 10 * 1024 * 1024) return toast.error("O documento não pode exceder 10 MB.");
    if (!cycle) return;
    const reader = new FileReader(); reader.onload = () => uploadDocument.mutate({ cycleId: cycle.id, documentType, fileName: file.name, mimeType: file.type as "application/pdf" | "image/jpeg" | "image/png", contentBase64: String(reader.result).split(",")[1] || "" }); reader.readAsDataURL(file);
    event.target.value = "";
  };

  return <div className="mx-auto max-w-7xl space-y-7">
    <Heading eyebrow={isManager ? "Consulta administrativa" : "Espaço da escola"} title={isManager ? "Escolas e inventários" : "Inventário patrimonial"} description={isManager ? "Consulte uma escola individualmente ou aceda à visão agregada no painel de gestão e consolidação." : "Registe os bens, documentos assinados e situações pendentes antes de submeter o inventário anual."} action={<div className="flex items-center gap-2"><Select value={String(year)} onValueChange={value => setYear(Number(value))}><SelectTrigger className="w-[110px] bg-white"><SelectValue /></SelectTrigger><SelectContent>{[YEAR - 1, YEAR, YEAR + 1].map(option => <SelectItem key={option} value={String(option)}>{option}</SelectItem>)}</SelectContent></Select>{isManager && <Button className="bg-[#0c4a3e] hover:bg-[#083a31]" onClick={() => { setEditingSchool(null); setSchoolDialog(true); }}><Plus className="mr-2 size-4" />Nova escola</Button>}</div>} />
    {schoolsQuery.isLoading ? <LoadingPanel /> : !schoolsQuery.data?.length ? <EmptyState icon={Building2} title="Ainda não há escolas associadas">{isManager ? <>Registe a primeira escola para abrir o ciclo de inventário e atribuir os utilizadores responsáveis.</> : <>A equipa gestora ainda não associou o seu acesso a uma escola. Peça ao responsável pela plataforma para o configurar.</>}</EmptyState> : <>
      <div className="rounded-2xl border border-[#dce7dc] bg-white p-3"><div className="flex flex-col gap-2 sm:flex-row sm:items-center"><Input value={schoolSearch} onChange={event => setSchoolSearch(event.target.value)} placeholder="Pesquisar por escola, código INEP ou município" className="h-10 border-[#d9e5da] bg-[#fbfdf9] sm:max-w-md" /><p className="text-xs text-[#718277]">{filteredSchools.length} de {schoolsQuery.data.length} escolas</p></div><div className="mt-3 flex gap-2 overflow-x-auto pb-1">{filteredSchools.length ? filteredSchools.map((school: any) => <button key={school.id} onClick={() => setSchoolId(school.id)} className={`min-w-[220px] rounded-2xl border px-4 py-3 text-left transition ${school.id === schoolId ? "border-[#1e604a] bg-[#e8f1e8] shadow-sm" : "border-[#dbe5dc] bg-white hover:border-[#9ebca7]"}`}><p className="truncate text-sm font-semibold text-[#1d3c31]">{school.name}</p><p className="mt-1 truncate text-xs text-[#6b7e72]">INEP {school.schoolCode || "—"} · {school.city || "Município não informado"}</p></button>) : <p className="px-3 py-4 text-sm text-[#718277]">Nenhuma escola corresponde à pesquisa.</p>}</div></div>
      {overviewQuery.isLoading || !overview ? <LoadingPanel /> : <>
        <Card className="overflow-hidden border-[#dce7dc] bg-white shadow-[0_8px_30px_rgba(19,61,45,.05)]"><CardContent className="grid gap-0 p-0 lg:grid-cols-[1.2fr_.8fr]"><div className="p-6 md:p-8"><div className="flex flex-wrap items-start justify-between gap-4"><div><div className="flex items-center gap-2"><p className="text-[11px] font-bold uppercase tracking-[.17em] text-[#5d7667]">{year} · Carga patrimonial</p>{cycle && <StatusBadge status={cycle.status} />}</div><h2 className="mt-2 font-serif text-2xl font-semibold text-[#173b30]">{overview.school.name}</h2><p className="mt-2 text-sm text-[#62756a]">{overview.school.city || "Município não informado"}{overview.school.regionalOffice ? ` · ${overview.school.regionalOffice}` : ""}</p></div><div className="flex gap-2">{isManager && <Button variant="outline" onClick={() => { setEditingSchool(overview.school); setSchoolDialog(true); }}><PencilLine className="mr-2 size-4" />Editar</Button>}{isManager && <Button variant="outline" onClick={() => setAccessDialog(true)}><UsersRound className="mr-2 size-4" />Acessos</Button>}</div></div>
          <div className="mt-7 grid grid-cols-2 gap-3 md:grid-cols-4"><MiniStat label="Itens" value={String(overview.items?.length ?? 0)} /><MiniStat label="Valor registrado" value={money(totalValue)} /><MiniStat label="Pendências" value={String(overview.issues?.filter((issue: any) => issue.resolutionStatus !== "resolved").length ?? 0)} /><MiniStat label="Documentos" value={`${documentTypes.size}/3`} /></div>
        </div><div className="bg-[#123f34] p-6 text-white md:p-8"><p className="text-xs font-bold uppercase tracking-[.16em] text-[#bad2c2]">Progresso de submissão</p><p className="mt-3 font-serif text-4xl font-semibold">{Math.round((completion / 4) * 100)}%</p><div className="mt-4 h-2 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-full bg-[#d9c07c]" style={{ width: `${(completion / 4) * 100}%` }} /></div><p className="mt-4 text-sm leading-6 text-[#c7d8cd]">Inclua itens, um ou mais integrantes da subcomissão e os documentos assinados para enviar o inventário.</p>{cycle && editable && !submissionRequirements.ready && <div role="alert" className="mt-4 rounded-xl border border-amber-200/30 bg-white/10 px-3 py-3"><p className="text-xs font-bold uppercase tracking-[.12em] text-[#f0d98f]">Exigências pendentes</p><ul className="mt-2 space-y-1 text-xs leading-5 text-[#e2eee5]">{submissionRequirements.missing.map(requirement => <li key={requirement}>• {requirement}</li>)}</ul></div>}{canCreateCycle ? <Button onClick={() => schoolId && createCycle.mutate({ schoolId, year })} disabled={createCycle.isPending} className="mt-6 w-full bg-[#d9c07c] text-[#17372f] hover:bg-[#ead38f]"><Plus className="mr-2 size-4" />Iniciar inventário {year}</Button> : cycle && editable ? <Button onClick={handleSubmit} disabled={submitCycle.isPending} className="mt-6 w-full bg-[#d9c07c] text-[#17372f] hover:bg-[#ead38f]">{submitCycle.isPending ? <Loader2 className="mr-2 size-4 animate-spin" /> : <Send className="mr-2 size-4" />}{submissionRequirements.ready ? "Submeter para validação" : "Concluir exigências para submeter"}</Button> : cycle ? <div className="mt-6 rounded-xl bg-white/10 px-3 py-3 text-sm text-[#dbe9df]">{cycle.status === "returned" ? "Corrija os apontamentos da equipe gestora e submeta novamente." : "A equipe gestora está acompanhando este inventário."}</div> : null}</div></CardContent></Card>
        {cycle && <div className="grid gap-6 xl:grid-cols-[1.45fr_.85fr]">
          <div className="space-y-6"><InventoryItemsCard items={overview.items} categories={categoriesQuery.data ?? []} editable={editable} onAdd={() => { setEditingItem(null); setItemDialog(true); }} onEdit={item => { setEditingItem(item); setItemDialog(true); }} onDelete={id => deleteItem.mutate({ itemId: id })} /><IssuesCard issues={overview.issues} editable={editable} onAdd={() => setIssueDialog(true)} onDelete={id => deleteIssue.mutate({ issueId: id })} /><NotesCard notes={overview.notes} editable={editable} onEdit={openNotes} /></div>
          <div className="space-y-6"><CommitteeCard members={overview.members} editable={editable} onEdit={openCommittee} /><DocumentsCard documents={overview.documents} editable={editable} uploading={uploadDocument.isPending} onUpload={handleFile} onRemove={id => removeDocument.mutate({ documentId: id })} /><ValidationCard cycle={cycle} history={overview.history} /></div>
        </div>}
      </>}
    </>}
    <SchoolFormDialog open={schoolDialog} onOpenChange={setSchoolDialog} school={editingSchool} pending={createSchool.isPending || updateSchool.isPending} onSave={fields => { if (editingSchool) updateSchool.mutate({ schoolId: editingSchool.id, ...fields }); else createSchool.mutate(fields); }} />
    {cycle && <ItemDialog open={itemDialog} onOpenChange={value => { setItemDialog(value); if (!value) setEditingItem(null); }} item={editingItem} categories={categoriesQuery.data ?? []} pending={addItem.isPending || updateItem.isPending} onSave={fields => editingItem ? updateItem.mutate({ itemId: editingItem.id, cycleId: cycle.id, ...fields }) : addItem.mutate({ cycleId: cycle.id, ...fields })} />}
    {cycle && <IssueDialog open={issueDialog} onOpenChange={setIssueDialog} pending={addIssue.isPending} onSave={fields => addIssue.mutate({ cycleId: cycle.id, ...fields })} />}
    <CommitteeDialog open={committeeDialog} onOpenChange={setCommitteeDialog} members={committee} setMembers={setCommittee} pending={setCommitteeMutation.isPending} onSave={() => cycle && setCommitteeMutation.mutate({ cycleId: cycle.id, members: committee })} />
    <NotesDialog open={notesDialog} onOpenChange={setNotesDialog} notes={notes} setNotes={setNotes} pending={setNotesMutation.isPending} onSave={() => cycle && setNotesMutation.mutate({ cycleId: cycle.id, ...notes })} />
    {isManager && schoolId && <AccessDialog open={accessDialog} onOpenChange={setAccessDialog} schoolId={schoolId} schoolName={overview?.school.name || ""} />}
  </div>;
}

function MiniStat({ label, value }: { label: string; value: string }) { return <div className="rounded-xl border border-[#e1e9e2] bg-[#fbfdf9] px-3 py-3"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#728378]">{label}</p><p className="mt-1 truncate text-lg font-semibold text-[#24473a]">{value}</p></div>; }
function LoadingPanel() { return <div className="flex min-h-56 items-center justify-center rounded-2xl border border-[#dce7dc] bg-white"><Loader2 className="size-6 animate-spin text-[#2d6a51]" /></div>; }

function InventoryItemsCard({ items, categories, editable, onAdd, onEdit, onDelete }: { items: any[]; categories: any[]; editable?: boolean; onAdd: () => void; onEdit: (item: any) => void; onDelete: (id: number) => void }) {
  const total = items?.reduce((sum, item) => sum + Number(item.totalValue), 0) ?? 0;
  const names = Object.fromEntries(categories.map(category => [category.code, category.label]));
  return <Card className="border-[#dce7dc]"><CardContent className="p-0"><SectionHead icon={Archive} title="Inventário detalhado" subtitle="Bens móveis registados na carga patrimonial." action={editable ? <Button size="sm" className="bg-[#0c4a3e] hover:bg-[#083a31]" onClick={onAdd}><Plus className="mr-1.5 size-4" />Adicionar item</Button> : undefined} /><div className="overflow-x-auto"><table className="w-full min-w-[820px] text-left text-sm"><thead className="border-y border-[#e4ece5] bg-[#f7faf6] text-[10px] font-bold uppercase tracking-[.1em] text-[#6c7e72]"><tr><th className="px-5 py-3">Património</th><th className="px-4 py-3">Descrição</th><th className="px-4 py-3">Classificação</th><th className="px-4 py-3">Conservação</th><th className="px-4 py-3 text-right">Quantidade</th><th className="px-4 py-3 text-right">Valor total</th><th className="px-4 py-3">Situação</th>{editable && <th className="w-20 px-4 py-3" />}</tr></thead><tbody>{items?.length ? items.map((item: any) => <tr key={item.id} className="border-b border-[#edf2ed] last:border-0"><td className="px-5 py-4 font-mono text-xs font-semibold text-[#265c49]">{item.propertyNumber}</td><td className="max-w-64 px-4 py-4"><p className="font-medium text-[#213f34]">{item.description}</p>{item.technicalDetails && <p className="mt-1 line-clamp-1 text-xs text-[#708177]">{item.technicalDetails}</p>}</td><td className="px-4 py-4"><p className="font-mono text-xs text-[#245a48]">{item.expenseCode}</p><p className="mt-1 max-w-40 text-xs text-[#6b7d72]">{names[item.expenseCode]}</p></td><td className="px-4 py-4 text-[#4e6559]">{item.conservationState}</td><td className="px-4 py-4 text-right font-medium">{item.quantity}</td><td className="px-4 py-4 text-right font-semibold text-[#244b3b]">{money(item.totalValue)}</td><td className="px-4 py-4 text-xs text-[#4e6559]">{item.currentSituation}</td>{editable && <td className="px-4 py-4"><div className="flex items-center gap-1"><button type="button" onClick={() => onEdit(item)} className="rounded-lg p-1.5 text-[#2d6a51] hover:bg-[#e8f1e8]" aria-label="Editar item" title="Editar item"><PencilLine className="size-4" /></button><button type="button" onClick={() => onDelete(item.id)} className="rounded-lg p-1.5 text-[#9a5548] hover:bg-rose-50" aria-label="Remover item" title="Remover item"><X className="size-4" /></button></div></td>}</tr>) : <tr><td colSpan={editable ? 8 : 7} className="px-5 py-10 text-center text-sm text-[#728177]">Nenhum bem registado neste inventário.</td></tr>}</tbody><tfoot className="border-t border-[#dce7dc] bg-[#f8fbf7]"><tr><td colSpan={5} className="px-5 py-4 text-right text-xs font-bold uppercase tracking-[.1em] text-[#526d5e]">Total registado</td><td className="px-4 py-4 text-right font-semibold text-[#173b30]">{money(total)}</td><td colSpan={editable ? 2 : 1} /></tr></tfoot></table></div></CardContent></Card>;
}
function IssuesCard({ issues, editable, onAdd, onDelete }: { issues: any[]; editable?: boolean; onAdd: () => void; onDelete: (id: number) => void }) {
  return <Card className="border-[#dce7dc]"><CardContent className="p-0"><SectionHead icon={CircleAlert} title="Pendências e ocorrências" subtitle="Situações encontradas, providências e resultados alcançados." action={editable ? <Button size="sm" variant="outline" onClick={onAdd}><Plus className="mr-1.5 size-4" />Registar pendência</Button> : undefined} />{issues?.length ? <div className="divide-y divide-[#e9efea]">{issues.map((issue: any) => <div key={issue.id} className="flex gap-3 px-5 py-4"><div className={`mt-0.5 flex size-8 shrink-0 items-center justify-center rounded-lg ${issue.resolutionStatus === "resolved" ? "bg-emerald-100 text-emerald-700" : "bg-amber-100 text-amber-700"}`}><CircleAlert className="size-4" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-semibold text-[#213f34]">{issue.description}</p><Badge variant="outline" className="border-[#d6e1d7] text-[10px] text-[#4e6759]">{issueLabels[issue.issueType]}</Badge><Badge className={`border-0 text-[10px] ${issue.resolutionStatus === "resolved" ? "bg-emerald-100 text-emerald-800" : "bg-amber-100 text-amber-800"}`}>{issue.resolutionStatus === "resolved" ? "Resolvida" : issue.resolutionStatus === "in_progress" ? "Em tratamento" : "Aberta"}</Badge></div><p className="mt-1 text-sm leading-5 text-[#64766b]">{issue.pendingDescription}</p>{issue.measuresTaken && <p className="mt-2 rounded-lg bg-[#f7faf6] px-3 py-2 text-xs leading-5 text-[#52685b]"><b>Medidas adotadas:</b> {issue.measuresTaken}</p>}<p className="mt-2 text-xs text-[#718277]">{[issue.propertyNumber && `Património ${issue.propertyNumber}`, issue.location, issue.totalValue && money(issue.totalValue)].filter(Boolean).join(" · ")}</p></div>{editable && <button onClick={() => onDelete(issue.id)} className="self-start rounded-lg p-1.5 text-[#9a5548] hover:bg-rose-50" aria-label="Remover pendência"><X className="size-4" /></button>}</div>)}</div> : <div className="px-5 pb-6"><EmptyState icon={CheckCircle2} title="Sem pendências registadas">Se identificar uma divergência, transferência, doação ou bem não localizado, registe-a aqui.</EmptyState></div>}</CardContent></Card>;
}

function NotesCard({ notes, editable, onEdit }: { notes: any; editable?: boolean; onEdit: () => void }) { const active = notes?.problemsFound || notes?.quantityDivergences || notes?.valueDivergences; return <Card className="border-[#dce7dc]"><CardContent className="p-0"><SectionHead icon={ClipboardCheck} title="Problemas e divergências" subtitle="Registo narrativo das dificuldades e divergências entre planilhas." action={editable ? <Button size="sm" variant="outline" onClick={onEdit}><PencilLine className="mr-1.5 size-4" />{active ? "Editar" : "Registar"}</Button> : undefined} />{active ? <div className="grid gap-3 px-5 pb-5 md:grid-cols-3"><NotePreview title="Problemas encontrados" value={notes.problemsFound} /><NotePreview title="Divergências quantitativas" value={notes.quantityDivergences} /><NotePreview title="Divergências de valores" value={notes.valueDivergences} /></div> : <p className="px-5 pb-5 text-sm text-[#718277]">Não há problemas ou divergências narrativas registados.</p>}</CardContent></Card>; }
function NotePreview({ title, value }: { title: string; value?: string | null }) { return <div className="rounded-xl bg-[#f7faf6] p-3"><p className="text-[10px] font-bold uppercase tracking-[.1em] text-[#6a8072]">{title}</p><p className="mt-2 line-clamp-4 text-sm leading-5 text-[#52665b]">{value || "Não informado."}</p></div>; }
function CommitteeCard({ members, editable, onEdit }: { members: any[]; editable?: boolean; onEdit: () => void }) { return <Card className="border-[#dce7dc]"><CardContent className="p-0"><SectionHead icon={UsersRound} title="Subcomissão" subtitle="De 1 a 25 integrantes responsáveis pela conferência do inventário." action={editable ? <Button size="sm" variant="outline" onClick={onEdit}><PencilLine className="mr-1.5 size-4" />Editar</Button> : undefined} />{members?.length ? <div className="space-y-2 px-5 pb-5">{members.map((member: any) => <div key={member.id} className="flex items-center gap-3 rounded-xl bg-[#f7faf6] p-3"><div className="flex size-8 items-center justify-center rounded-full bg-[#dcebe0] text-xs font-bold text-[#266248]">{member.name.charAt(0)}</div><div className="min-w-0"><p className="truncate text-sm font-semibold text-[#274337]">{member.name}{member.isPresident ? " · Presidente" : ""}</p><p className="truncate text-xs text-[#728177]">{member.jobTitle} · MASP {member.masp}</p></div></div>)}</div> : <p className="px-5 pb-5 text-sm text-[#718277]">Registre ao menos um integrante da subcomissão para avançar.</p>}</CardContent></Card>; }

function DocumentsCard({ documents, editable, uploading, onUpload, onRemove }: { documents: any[]; editable?: boolean; uploading: boolean; onUpload: (event: ChangeEvent<HTMLInputElement>, type: "opening_minutes" | "responsibility_term" | "closing_minutes") => void; onRemove: (id: number) => void }) { return <Card className="border-[#dce7dc]"><CardContent className="p-0"><SectionHead icon={FileCheck2} title="Documentos assinados" subtitle="Organizados por escola e por tipo documental." /> <div className="space-y-2 px-5 pb-5">{(["opening_minutes", "responsibility_term", "closing_minutes"] as const).map(type => { const file = documents?.filter((document: any) => document.documentType === type).at(-1); return <div key={type} className="rounded-xl border border-[#e3ebe4] bg-[#fcfdfb] p-3"><div className="flex items-center gap-3"><div className={`flex size-9 shrink-0 items-center justify-center rounded-lg ${file ? "bg-emerald-100 text-emerald-700" : "bg-[#edf2ed] text-[#718377]"}`}>{file ? <CheckCircle2 className="size-4" /> : <FileText className="size-4" />}</div><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-[#294539]">{docLabels[type]}</p><p className="truncate text-xs text-[#74857a]">{file ? file.fileName : "Documento pendente"}</p></div>{file && <a href={file.storageUrl} target="_blank" rel="noreferrer" className="rounded-lg px-2 py-1.5 text-xs font-semibold text-[#216047] hover:bg-[#e8f1e8]">Ver</a>}{editable && <label data-tutorial-id={`document-${type}`} className="rounded-lg bg-red-600 px-2.5 py-1.5 text-xs font-semibold text-white hover:bg-red-700">{uploading ? "A enviar" : file ? "Substituir" : "Enviar"}<input type="file" accept="application/pdf,image/jpeg,image/png" className="hidden" disabled={uploading} onChange={event => onUpload(event, type)} /></label>}{editable && file && <button onClick={() => onRemove(file.id)} className="p-1 text-[#985549] hover:bg-rose-50" aria-label="Remover documento"><X className="size-4" /></button>}</div></div>; })}</div></CardContent></Card>; }
function ValidationCard({ cycle, history }: { cycle: any; history: any[] }) { return <Card className="border-[#dce7dc] bg-[#fbfdf9]"><CardContent className="p-5"><div className="flex gap-3"><div className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-[#e9f0e9] text-[#32674f]"><ShieldAlert className="size-4" /></div><div><p className="text-sm font-semibold text-[#264438]">Acompanhamento da validação</p><p className="mt-1 text-xs leading-5 text-[#6b7d72]">Estado atual: <span className="font-semibold">{statusLabels[cycle.status]}</span></p></div></div>{cycle.reviewNotes && <p className="mt-4 rounded-xl bg-white p-3 text-sm leading-5 text-[#53675b]"><b>Nota da equipa gestora:</b> {cycle.reviewNotes}</p>}{history?.length ? <div className="mt-4 border-t border-[#e2ebe3] pt-3">{history.slice(-3).reverse().map((entry: any) => <div key={entry.id} className="mb-2 text-xs text-[#718277]"><span className="font-semibold text-[#425f50]">{statusLabels[entry.action]}</span> · {new Date(entry.createdAt).toLocaleDateString("pt-PT")}</div>)}</div> : null}</CardContent></Card>; }
function SectionHead({ icon: Icon, title, subtitle, action }: { icon: typeof Archive; title: string; subtitle: string; action?: React.ReactNode }) { return <div className="flex flex-wrap items-start justify-between gap-3 p-5 pb-4"><div className="flex gap-3"><div className="flex size-9 shrink-0 items-center justify-center rounded-xl bg-[#e8f1e8] text-[#276249]"><Icon className="size-4" /></div><div><h3 className="font-semibold text-[#203f33]">{title}</h3><p className="mt-0.5 text-xs leading-5 text-[#6b7d72]">{subtitle}</p></div></div>{action}</div>; }

function SchoolFormDialog({ open, onOpenChange, school, pending, onSave }: { open: boolean; onOpenChange: (value: boolean) => void; school: any; pending: boolean; onSave: (fields: any) => void }) { return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-3xl"><DialogHeader><DialogTitle>{school ? "Editar escola" : "Registar escola"}</DialogTitle><DialogDescription>Identificação institucional, responsável e direção da escola.</DialogDescription></DialogHeader><form onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); onSave(Object.fromEntries(Object.entries({ name: safeText(data.get("name")), schoolCode: safeText(data.get("schoolCode")) || null, city: safeText(data.get("city")) || null, regionalOffice: safeText(data.get("regionalOffice")) || null, email: safeText(data.get("email")) || null, phone: safeText(data.get("phone")) || null, responsibleName: safeText(data.get("responsibleName")) || null, responsibleMasp: safeText(data.get("responsibleMasp")) || null, responsibleRole: safeText(data.get("responsibleRole")) || null, directorName: safeText(data.get("directorName")) || null, directorMasp: safeText(data.get("directorMasp")) || null }))); }} className="space-y-5"><div className="grid gap-4 sm:grid-cols-2"><Field label="Nome da escola"><Input required name="name" defaultValue={school?.name} placeholder="Ex.: Escola Estadual ..." /></Field><Field label="Código da escola"><Input name="schoolCode" defaultValue={school?.schoolCode || ""} /></Field><Field label="Município"><Input name="city" defaultValue={school?.city || ""} /></Field><Field label="Superintendência / regional"><Input name="regionalOffice" defaultValue={school?.regionalOffice || ""} /></Field><Field label="E-mail institucional"><Input type="email" name="email" defaultValue={school?.email || ""} /></Field><Field label="Telefone"><Input name="phone" defaultValue={school?.phone || ""} /></Field></div><div className="border-t border-[#e5ece5] pt-5"><p className="mb-3 text-xs font-bold uppercase tracking-[.13em] text-[#637a6c]">Responsável pelo inventário</p><div className="grid gap-4 sm:grid-cols-3"><Field label="Nome"><Input name="responsibleName" defaultValue={school?.responsibleName || ""} /></Field><Field label="Cargo"><Input name="responsibleRole" defaultValue={school?.responsibleRole || ""} /></Field><Field label="MASP"><Input name="responsibleMasp" defaultValue={school?.responsibleMasp || ""} /></Field></div></div><div className="border-t border-[#e5ece5] pt-5"><p className="mb-3 text-xs font-bold uppercase tracking-[.13em] text-[#637a6c]">Direção</p><div className="grid gap-4 sm:grid-cols-2"><Field label="Nome do(a) diretor(a)"><Input name="directorName" defaultValue={school?.directorName || ""} /></Field><Field label="MASP"><Input name="directorMasp" defaultValue={school?.directorMasp || ""} /></Field></div></div><DialogFooter><Button type="button" variant="outline" onClick={() => onOpenChange(false)}>Cancelar</Button><Button type="submit" className="bg-[#0c4a3e] hover:bg-[#083a31]" disabled={pending}>{pending && <Loader2 className="mr-2 size-4 animate-spin" />}{school ? "Guardar alterações" : "Registar escola"}</Button></DialogFooter></form></DialogContent></Dialog>; }

function ItemDialog({ open, onOpenChange, item, categories, pending, onSave }: { open: boolean; onOpenChange: (value: boolean) => void; item?: any; categories: any[]; pending: boolean; onSave: (fields: any) => void }) {
  const [scannerOpen, setScannerOpen] = useState(false);
  const [propertyMode, setPropertyMode] = useState<"required" | "not_applicable">("required");
  const [propertyNumber, setPropertyNumber] = useState("");

  useEffect(() => {
    if (open) {
      const existingProperty = String(item?.propertyNumber ?? "");
      setScannerOpen(false);
      setPropertyNumber(existingProperty === "Não se aplica" ? "Não se aplica" : existingProperty);
      setPropertyMode(existingProperty === "Não se aplica" ? "not_applicable" : "required");
    }
  }, [open, item]);

  return <><Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-3xl"><DialogHeader><DialogTitle>{item ? "Editar bem patrimonial" : "Adicionar bem patrimonial"}</DialogTitle><DialogDescription>O valor total é calculado automaticamente a partir da quantidade e do valor unitário.</DialogDescription></DialogHeader><form key={`${item?.id ?? "new"}-${open}`} onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); const value = propertyMode === "not_applicable" ? "Não se aplica" : safeText(data.get("propertyNumber")); if (!value) { toast.error("Informe o número de patrimônio ou selecione 'Não se aplica'."); return; } onSave({ propertyNumber: value, quantity: Number(data.get("quantity")), description: safeText(data.get("description")), technicalDetails: safeText(data.get("technicalDetails")) || null, expenseCode: safeText(data.get("expenseCode")), conservationCode: safeText(data.get("conservationCode")) || null, conservationState: safeText(data.get("conservationState")), unitValue: Number(data.get("unitValue")), currentSituation: safeText(data.get("currentSituation")) }); }} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="N.º de património"><div className="mb-2 flex flex-wrap gap-2"><Button type="button" variant={propertyMode === "required" ? "default" : "outline"} onClick={() => { setPropertyMode("required"); setPropertyNumber(""); }} className={propertyMode === "required" ? "bg-[#0c4a3e] hover:bg-[#083a31]" : ""}>Possui patrimônio</Button><Button type="button" variant={propertyMode === "not_applicable" ? "default" : "outline"} onClick={() => { setPropertyMode("not_applicable"); setPropertyNumber("Não se aplica"); }} className={propertyMode === "not_applicable" ? "bg-[#0c4a3e] hover:bg-[#083a31]" : ""}>Não se aplica</Button></div><div className="flex gap-2"><Input name="propertyNumber" value={propertyNumber} onChange={event => { setPropertyMode("required"); setPropertyNumber(event.target.value); }} disabled={propertyMode === "not_applicable"} required={propertyMode === "required"} className="min-w-0" placeholder={propertyMode === "not_applicable" ? "Não se aplica" : "Digite ou leia pela câmera"} /><Button type="button" variant="outline" disabled={propertyMode === "not_applicable"} onClick={() => setScannerOpen(true)} aria-label="Ler código de barras pela câmera" title="Ler código de barras pela câmera" className="shrink-0 px-3"><ScanLine className="mr-1.5 size-4" />Ler</Button></div><p className="text-[11px] leading-4 text-[#718277]">{propertyMode === "not_applicable" ? "Use esta opção quando o bem não possuir número de patrimônio." : "Informe o número de patrimônio ou selecione 'Não se aplica'."}</p></Field><Field label="Quantidade"><Input name="quantity" required type="number" min="1" defaultValue={item?.quantity ?? 1} /></Field><Field label="Descrição do bem" className="sm:col-span-2"><Input name="description" required defaultValue={item?.description ?? ""} placeholder="Ex.: Mesa em L" /></Field><Field label="Detalhes técnicos" className="sm:col-span-2"><Textarea name="technicalDetails" defaultValue={item?.technicalDetails ?? ""} placeholder="Marca, modelo, dimensões ou outra referência." /></Field><Field label="Código de despesa"><Select name="expenseCode" defaultValue={item?.expenseCode ?? "52.14"}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{(categories?.length ? categories : expenseCodes.map(code => ({ code, label: code }))).map((category: any) => <SelectItem key={category.code} value={category.code}>{category.code} · {category.label}</SelectItem>)}</SelectContent></Select></Field><Field label="Código de conservação"><Input name="conservationCode" defaultValue={item?.conservationCode ?? ""} placeholder="Ex.: 2 - Bom" /></Field><Field label="Estado de conservação"><Select name="conservationState" defaultValue={item?.conservationState ?? "Bom"}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Novo", "Bom", "Regular", "Mau", "Inservível"].map(state => <SelectItem key={state} value={state}>{state}</SelectItem>)}</SelectContent></Select></Field><Field label="Valor unitário (R$)"><Input name="unitValue" required type="number" min="0" step="0.01" defaultValue={item?.unitValue ?? ""} /></Field><Field label="Situação atual" className="sm:col-span-2"><Input name="currentSituation" required defaultValue={item?.currentSituation ?? "Em uso"} placeholder="Ex.: Em uso, estocado, em manutenção" /></Field></div><DialogFooter><Button type="button" variant="outline" onClick={() => onOpenChange(false)}>Cancelar</Button><Button disabled={pending} type="submit" className="bg-[#0c4a3e] hover:bg-[#083a31]">{pending && <Loader2 className="mr-2 size-4 animate-spin" />}{item ? "Guardar alterações" : "Adicionar item"}</Button></DialogFooter></form></DialogContent></Dialog><BarcodeScannerDialog open={scannerOpen} onOpenChange={setScannerOpen} onDetected={code => { setPropertyMode("required"); setPropertyNumber(code); setScannerOpen(false); toast.success("Número patrimonial preenchido pela câmera."); }} /></>;
}
function IssueDialog({ open, onOpenChange, pending, onSave }: { open: boolean; onOpenChange: (value: boolean) => void; pending: boolean; onSave: (fields: any) => void }) { const [status, setStatus] = useState("open"); const [type, setType] = useState("not_found"); return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-3xl"><DialogHeader><DialogTitle>Registar pendência</DialogTitle><DialogDescription>Inclua a ocorrência, providências adotadas e a situação atual para o relatório consolidado.</DialogDescription></DialogHeader><form onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); onSave({ issueType: type, propertyNumber: safeText(data.get("propertyNumber")) || null, quantity: data.get("quantity") ? Number(data.get("quantity")) : null, description: safeText(data.get("description")), conservationState: safeText(data.get("conservationState")) || null, location: safeText(data.get("location")) || null, totalValue: data.get("totalValue") ? Number(data.get("totalValue")) : null, originBody: safeText(data.get("originBody")) || null, currentSituation: safeText(data.get("currentSituation")) || null, pendingDescription: safeText(data.get("pendingDescription")), measuresTaken: safeText(data.get("measuresTaken")) || null, resolutionStatus: status }); }} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Tipo de ocorrência"><Select value={type} onValueChange={setType}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{Object.entries(issueLabels).map(([key, label]) => <SelectItem key={key} value={key}>{label}</SelectItem>)}</SelectContent></Select></Field><Field label="Estado de acompanhamento"><Select value={status} onValueChange={setStatus}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="open">Aberta</SelectItem><SelectItem value="in_progress">Em tratamento</SelectItem><SelectItem value="resolved">Resolvida</SelectItem></SelectContent></Select></Field><Field label="Descrição resumida" className="sm:col-span-2"><Input required name="description" placeholder="Ex.: Mesa no depósito sem localização patrimonial" /></Field><Field label="N.º de património"><Input name="propertyNumber" /></Field><Field label="Quantidade"><Input type="number" min="1" name="quantity" /></Field><Field label="Estado de conservação"><Input name="conservationState" /></Field><Field label="Local / bloco"><Input name="location" /></Field><Field label="Valor total (R$)"><Input type="number" min="0" step="0.01" name="totalValue" /></Field><Field label="Órgão de origem"><Input name="originBody" /></Field><Field label="Situação atual" className="sm:col-span-2"><Input name="currentSituation" /></Field><Field label="Pendência identificada" className="sm:col-span-2"><Textarea required name="pendingDescription" /></Field><Field label="Medidas adotadas e resultados" className="sm:col-span-2"><Textarea name="measuresTaken" /></Field></div><DialogFooter><Button type="button" variant="outline" onClick={() => onOpenChange(false)}>Cancelar</Button><Button disabled={pending} type="submit" className="bg-[#0c4a3e] hover:bg-[#083a31]">{pending && <Loader2 className="mr-2 size-4 animate-spin" />}Guardar pendência</Button></DialogFooter></form></DialogContent></Dialog>; }

function CommitteeDialog({ open, onOpenChange, members, setMembers, pending, onSave }: { open: boolean; onOpenChange: (value: boolean) => void; members: any[]; setMembers: (members: any[]) => void; pending: boolean; onSave: () => void }) { const edit = (index: number, field: string, value: string | boolean) => setMembers(members.map((member, position) => position === index ? { ...member, [field]: value } : field === "isPresident" && value ? { ...member, isPresident: false } : member)); const remove = (index: number) => { if (members.length > 1) setMembers(members.filter((_, position) => position !== index)); }; return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-4xl"><DialogHeader><DialogTitle>Subcomissão de inventário</DialogTitle><DialogDescription>Registre de 1 a 25 integrantes responsáveis. Um integrante pode ser identificado como presidente da comissão.</DialogDescription></DialogHeader><div className="space-y-3"><p className="text-xs font-semibold text-[#5c7567]">{members.length} de 25 integrante{members.length === 1 ? "" : "s"} cadastrado{members.length === 1 ? "" : "s"}</p>{members.map((member, index) => <div key={index} className="grid gap-3 rounded-xl border border-[#e1e9e2] bg-[#fbfdf9] p-4 md:grid-cols-[1.1fr_1fr_.55fr_auto_auto]"><Field label="Nome"><Input value={member.name} onChange={event => edit(index, "name", event.target.value)} /></Field><Field label="Cargo"><Input value={member.jobTitle} onChange={event => edit(index, "jobTitle", event.target.value)} /></Field><Field label="MASP"><Input value={member.masp} onChange={event => edit(index, "masp", event.target.value)} /></Field><label className="flex items-end gap-2 pb-2 text-xs font-semibold text-[#4e6559]"><input checked={member.isPresident} onChange={event => edit(index, "isPresident", event.target.checked)} type="checkbox" />Presidente</label><Button type="button" variant="ghost" size="icon" className="self-end text-[#985549] hover:bg-rose-50 hover:text-[#7d4035]" aria-label="Remover integrante" disabled={members.length === 1} onClick={() => remove(index)}><X className="size-4" /></Button></div>)}<Button type="button" variant="outline" size="sm" disabled={members.length >= 25} onClick={() => setMembers([...members, createCommitteeMember(false)])}><Plus className="mr-1.5 size-4" />{members.length >= 25 ? "Limite de 25 integrantes" : "Adicionar integrante"}</Button></div><DialogFooter><Button variant="outline" onClick={() => onOpenChange(false)}>Cancelar</Button><Button onClick={onSave} disabled={pending || members.some(member => !member.name.trim() || !member.jobTitle.trim() || !member.masp.trim())} className="bg-[#0c4a3e] hover:bg-[#083a31]">{pending && <Loader2 className="mr-2 size-4 animate-spin" />}Guardar subcomissão</Button></DialogFooter></DialogContent></Dialog>; }

function NotesDialog({ open, onOpenChange, notes, setNotes, pending, onSave }: { open: boolean; onOpenChange: (value: boolean) => void; notes: any; setNotes: (notes: any) => void; pending: boolean; onSave: () => void }) { return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent><DialogHeader><DialogTitle>Problemas e divergências</DialogTitle><DialogDescription>Descreva as dificuldades identificadas no levantamento e eventuais divergências entre registros.</DialogDescription></DialogHeader><div className="space-y-4"><Field label="Problemas e dificuldades encontrados"><Textarea value={notes.problemsFound} onChange={event => setNotes({ ...notes, problemsFound: event.target.value })} /></Field><Field label="Divergências quantitativas"><Textarea value={notes.quantityDivergences} onChange={event => setNotes({ ...notes, quantityDivergences: event.target.value })} /></Field><Field label="Divergências de valores"><Textarea value={notes.valueDivergences} onChange={event => setNotes({ ...notes, valueDivergences: event.target.value })} /></Field></div><DialogFooter><Button variant="outline" onClick={() => onOpenChange(false)}>Cancelar</Button><Button onClick={onSave} disabled={pending} className="bg-[#0c4a3e] hover:bg-[#083a31]">Guardar registo</Button></DialogFooter></DialogContent></Dialog>; }

function AccessDialog({ open, onOpenChange, schoolId, schoolName }: { open: boolean; onOpenChange: (value: boolean) => void; schoolId: number; schoolName: string }) { const utils = trpc.useUtils(); const usersQuery = trpc.school.listAssignableUsers.useQuery(undefined, { enabled: open }); const membersQuery = trpc.school.listMembers.useQuery({ schoolId }, { enabled: open }); const [userId, setUserId] = useState(""); const [role, setRole] = useState<"coordinator" | "contributor">("coordinator"); const assign = trpc.school.assignUser.useMutation({ onSuccess: async () => { toast.success("Acesso associado à escola."); setUserId(""); await membersQuery.refetch(); void utils.school.list.invalidate(); } }); return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent><DialogHeader><DialogTitle>Acessos da escola</DialogTitle><DialogDescription>Associe utilizadores que já tenham iniciado sessão na plataforma a {schoolName}.</DialogDescription></DialogHeader><div className="rounded-xl bg-[#f7faf6] p-4"><p className="text-xs leading-5 text-[#617569]">Cada utilizador só vê as escolas que lhe foram atribuídas. A equipa gestora possui acesso geral por perfil administrativo.</p></div><div className="grid gap-3 sm:grid-cols-[1fr_.55fr_auto]"><Select value={userId} onValueChange={setUserId}><SelectTrigger><SelectValue placeholder="Selecionar utilizador" /></SelectTrigger><SelectContent>{usersQuery.data?.filter((user: any) => user.role === "user").map((user: any) => <SelectItem key={user.id} value={String(user.id)}>{user.name || user.email || `Utilizador ${user.id}`}</SelectItem>)}</SelectContent></Select><Select value={role} onValueChange={value => setRole(value as "coordinator" | "contributor")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="coordinator">Coordenador</SelectItem><SelectItem value="contributor">Colaborador</SelectItem></SelectContent></Select><Button disabled={!userId || assign.isPending} onClick={() => assign.mutate({ schoolId, userId: Number(userId), accessRole: role })}>Associar</Button></div><div className="max-h-48 space-y-2 overflow-y-auto border-t border-[#e4ece5] pt-4">{membersQuery.data?.length ? membersQuery.data.map((entry: any) => <div key={entry.membership.id} className="flex items-center justify-between rounded-xl bg-[#fbfdfb] px-3 py-2"><div><p className="text-sm font-semibold text-[#2a4539]">{entry.user.name || entry.user.email}</p><p className="text-xs text-[#74857a]">{entry.user.email}</p></div><Badge variant="outline" className="border-[#d3e0d5] text-xs text-[#51705e]">{entry.membership.accessRole === "coordinator" ? "Coordenador" : "Colaborador"}</Badge></div>) : <p className="text-sm text-[#738277]">Não há acessos associados.</p>}</div></DialogContent></Dialog>; }

function ManagementPanel({ year, setYear }: { year: number; setYear: (year: number) => void }) { const dashboardQuery = trpc.management.dashboard.useQuery({ year }); const categoriesQuery = trpc.catalog.expenseCategories.useQuery(); const [issueStatus, setIssueStatus] = useState("all"); const [reviewing, setReviewing] = useState<any>(null); const dashboard = dashboardQuery.data; const categories = Object.fromEntries((categoriesQuery.data ?? []).map(category => [category.code, category.label])); const visibleIssues = useMemo(() => (dashboard?.pendingIssues ?? []).filter((issue: any) => issueStatus === "all" || issue.resolutionStatus === issueStatus), [dashboard?.pendingIssues, issueStatus]); if (dashboardQuery.isLoading || !dashboard) return <div className="mx-auto max-w-7xl"><LoadingPanel /></div>; const metric = dashboard.metrics; return <div className="mx-auto max-w-7xl space-y-7"><Heading eyebrow="Equipa gestora" title="Gestão e consolidação" description="Acompanhe o estado dos inventários, valide as submissões e exporte os consolidados de itens e pendências." action={<Select value={String(year)} onValueChange={value => setYear(Number(value))}><SelectTrigger className="w-[110px] bg-white"><SelectValue /></SelectTrigger><SelectContent>{[YEAR - 1, YEAR, YEAR + 1].map(option => <SelectItem key={option} value={String(option)}>{option}</SelectItem>)}</SelectContent></Select>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><MetricCard label="Escolas com ciclo" value={metric.schoolsWithCycles} icon={Building2} /><MetricCard label="Submetidos" value={metric.submitted} icon={Send} tone="amber" /><MetricCard label="Validados" value={metric.validated} icon={CheckCircle2} tone="emerald" /><MetricCard label="Pendências abertas" value={metric.openIssues} icon={CircleAlert} tone="rose" /><MetricCard label="Valor consolidado" value={money(metric.totalValue)} icon={Landmark} /></div><Card className="border-[#dce7dc]"><CardContent className="p-0"><SectionHead icon={ClipboardCheck} title="Validações por escola" subtitle="Abra, devolva com apontamentos ou valide os inventários submetidos." /><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-sm"><thead className="border-y border-[#e4ece5] bg-[#f7faf6] text-[10px] font-bold uppercase tracking-[.1em] text-[#6c7e72]"><tr><th className="px-5 py-3 text-left">Escola</th><th className="px-4 py-3 text-left">Situação</th><th className="px-4 py-3 text-right">Submissão</th><th className="px-5 py-3 text-right">Ação</th></tr></thead><tbody>{dashboard.cycles.length ? dashboard.cycles.map((entry: any) => <tr key={entry.cycle.id} className="border-b border-[#edf2ed]"><td className="px-5 py-4"><p className="font-semibold text-[#234136]">{entry.school.name}</p><p className="text-xs text-[#75867a]">{entry.school.city || "Sem município"}</p></td><td className="px-4 py-4"><StatusBadge status={entry.cycle.status} /></td><td className="px-4 py-4 text-right text-xs text-[#687a6e]">{entry.cycle.submittedAt ? new Date(entry.cycle.submittedAt).toLocaleDateString("pt-PT") : "—"}</td><td className="px-5 py-4 text-right"><Button size="sm" variant="outline" onClick={() => setReviewing(entry)}>Analisar <ChevronRight className="ml-1 size-4" /></Button></td></tr>) : <tr><td colSpan={4} className="px-5 py-10 text-center text-sm text-[#718277]">Nenhuma escola iniciou o inventário neste ano.</td></tr>}</tbody></table></div></CardContent></Card><div className="grid gap-6 xl:grid-cols-[1.05fr_.95fr]"><Card className="border-[#dce7dc]"><CardContent className="p-0"><SectionHead icon={Landmark} title="Resumo consolidado" subtitle="Quantidade e valores por código de despesa." action={<Button size="sm" variant="outline" onClick={() => downloadCsv(dashboard.consolidated.map((line: any) => ({ "Código de despesa": line.expenseCode, "Elemento / item": categories[line.expenseCode] || "", Quantidade: line.quantity, "Valor total (R$)": Number(line.totalValue).toFixed(2) })), `resumo-consolidado-${year}`)}><ArrowDownToLine className="mr-1.5 size-4" />Exportar</Button>} /><div className="max-h-[440px] overflow-auto"><table className="w-full text-sm"><thead className="sticky top-0 border-y border-[#e4ece5] bg-[#f7faf6] text-[10px] font-bold uppercase tracking-[.1em] text-[#6c7e72]"><tr><th className="px-5 py-3 text-left">Código</th><th className="px-4 py-3 text-left">Elemento / item</th><th className="px-4 py-3 text-right">Qtd.</th><th className="px-5 py-3 text-right">Valor</th></tr></thead><tbody>{dashboard.consolidated.map((line: any) => <tr key={line.expenseCode} className="border-b border-[#edf2ed]"><td className="px-5 py-3 font-mono text-xs font-semibold text-[#245b48]">{line.expenseCode}</td><td className="px-4 py-3 text-xs text-[#52675b]">{categories[line.expenseCode]}</td><td className="px-4 py-3 text-right">{line.quantity}</td><td className="px-5 py-3 text-right font-semibold text-[#24483a]">{money(line.totalValue)}</td></tr>)}{!dashboard.consolidated.length && <tr><td colSpan={4} className="px-5 py-10 text-center text-sm text-[#718277]">Os dados de consolidação aparecerão quando as escolas incluírem itens.</td></tr>}</tbody><tfoot className="sticky bottom-0 bg-[#edf5ed]"><tr><td colSpan={3} className="px-5 py-3 text-right text-xs font-bold uppercase tracking-[.12em] text-[#526d5d]">Total global</td><td className="px-5 py-3 text-right font-semibold text-[#183f31]">{money(metric.totalValue)}</td></tr></tfoot></table></div></CardContent></Card><Card className="border-[#dce7dc]"><CardContent className="p-0"><SectionHead icon={CircleAlert} title="Pendências consolidadas" subtitle="Acompanhamento de ocorrências de todas as escolas." action={<div className="flex gap-2"><Select value={issueStatus} onValueChange={setIssueStatus}><SelectTrigger className="h-8 w-[120px] text-xs"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas</SelectItem><SelectItem value="open">Abertas</SelectItem><SelectItem value="in_progress">Em tratamento</SelectItem><SelectItem value="resolved">Resolvidas</SelectItem></SelectContent></Select><Button size="sm" variant="outline" onClick={() => downloadCsv(visibleIssues.map((issue: any) => ({ Escola: issue.school, Tipo: issueLabels[issue.issueType], Descrição: issue.description, Património: issue.propertyNumber, Pendência: issue.pendingDescription, Medidas: issue.measuresTaken, Situação: issue.resolutionStatus === "open" ? "Aberta" : issue.resolutionStatus === "in_progress" ? "Em tratamento" : "Resolvida" })), `pendencias-consolidadas-${year}`)}><ArrowDownToLine className="size-4" /></Button></div>} /><div className="max-h-[440px] divide-y divide-[#edf2ed] overflow-auto">{visibleIssues.length ? visibleIssues.map((issue: any) => <div key={issue.id} className="px-5 py-4"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.1em] text-[#688073]">{issue.school}</p><p className="mt-1 font-semibold text-[#254337]">{issue.description}</p></div><Badge className={`border-0 text-[10px] ${issue.resolutionStatus === "resolved" ? "bg-emerald-100 text-emerald-800" : "bg-amber-100 text-amber-800"}`}>{issue.resolutionStatus === "resolved" ? "Resolvida" : issue.resolutionStatus === "in_progress" ? "Em tratamento" : "Aberta"}</Badge></div><p className="mt-2 text-xs leading-5 text-[#697c70]">{issue.pendingDescription}</p></div>) : <div className="px-5 py-10 text-center text-sm text-[#718277]">Não há pendências com este filtro.</div>}</div></CardContent></Card></div><ReviewDialog entry={reviewing} onClose={() => setReviewing(null)} onSaved={() => dashboardQuery.refetch()} /></div>; }
function MetricCard({ label, value, icon: Icon, tone = "green" }: { label: string; value: string | number; icon: typeof Building2; tone?: "green" | "amber" | "emerald" | "rose" }) { const tones: Record<string, string> = { green: "bg-[#e8f1e8] text-[#286149]", amber: "bg-amber-100 text-amber-700", emerald: "bg-emerald-100 text-emerald-700", rose: "bg-rose-100 text-rose-700" }; return <Card className="border-[#dce7dc]"><CardContent className="p-4"><div className={`flex size-9 items-center justify-center rounded-xl ${tones[tone]}`}><Icon className="size-4" /></div><p className="mt-4 text-[10px] font-bold uppercase tracking-[.1em] text-[#708175]">{label}</p><p className="mt-1 truncate text-xl font-semibold text-[#1e4134]">{value}</p></CardContent></Card>; }
function ReviewDialog({ entry, onClose, onSaved }: { entry: any; onClose: () => void; onSaved: () => void }) { const [status, setStatus] = useState("under_review"); const [note, setNote] = useState(""); useEffect(() => { if (entry) { setStatus(entry.cycle.status === "submitted" ? "under_review" : entry.cycle.status); setNote(entry.cycle.reviewNotes || ""); } }, [entry]); const changeStatus = trpc.management.changeStatus.useMutation({ onSuccess: () => { toast.success("Estado de validação atualizado."); onSaved(); onClose(); } }); const targets = entry?.cycle.status === "submitted" ? ["under_review", "returned", "validated"] : entry?.cycle.status === "under_review" ? ["returned", "validated"] : []; return <Dialog open={Boolean(entry)} onOpenChange={open => !open && onClose()}><DialogContent><DialogHeader><DialogTitle>Validar inventário</DialogTitle><DialogDescription>{entry?.school.name} · ciclo {entry?.cycle.year}</DialogDescription></DialogHeader>{entry && targets.length ? <><Field label="Novo estado"><Select value={status} onValueChange={setStatus}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{targets.map(target => <SelectItem key={target} value={target}>{statusLabels[target]}</SelectItem>)}</SelectContent></Select></Field><Field label={status === "returned" ? "Apontamentos obrigatórios para a escola" : "Nota para acompanhamento"}><Textarea value={note} onChange={event => setNote(event.target.value)} placeholder={status === "returned" ? "Indique as correções necessárias." : "Registe uma observação, se necessário."} /></Field><DialogFooter><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={changeStatus.isPending} onClick={() => changeStatus.mutate({ cycleId: entry.cycle.id, status: status as "under_review" | "returned" | "validated", note: note || null })} className="bg-[#0c4a3e] hover:bg-[#083a31]">{changeStatus.isPending && <Loader2 className="mr-2 size-4 animate-spin" />}Confirmar</Button></DialogFooter></> : <div className="rounded-xl bg-[#f6faf6] p-4 text-sm leading-6 text-[#62766a]">Este ciclo está em <b>{statusLabels[entry?.cycle.status]}</b> e não possui uma transição de validação disponível.</div>}</DialogContent></Dialog>; }
